#[derive(Clone, Debug)]
pub struct Member {
    pub team: &'static str,
    pub points: u32,
    pub active: bool,
}

pub fn team_report(teams: &[&'static str], members: &[Member]) -> Vec<String> {
    let mut totals: Vec<(&'static str, u32)> = Vec::new();

    for &team in teams {
        let mut sum = 0;
        let mut seen = false;
        for m in members {
            if m.team == team {
                seen = true;
                sum += m.points;
            }
        }
        if seen {
            totals.push((team, sum));
        }
    }

    totals.sort_by(|a, b| a.0.cmp(b.0));
    totals
        .into_iter()
        .map(|(team, total)| format!("{}:{}", team, total))
        .collect()
}

